selector_to_html = {"a[href=\"#symmetric-ribs-and-fins\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Symmetric ribs and fins<a class=\"headerlink\" href=\"#symmetric-ribs-and-fins\" title=\"Link to this heading\">\u00b6</a></h2><p>Set <code class=\"docutils literal notranslate\"><span class=\"pre\">enable_fin=True</span></code> on an independent section to include the existing\nsymmetric sidewall rib model in <code class=\"docutils literal notranslate\"><span class=\"pre\">R_coolant_per_len</span></code>. It represents half a shared\nrib on each side of a channel. The conduction calculation therefore uses twice\nthe individual sidewall thickness as the full rib thickness.</p>", "a[href=\"#select-thermal-surfaces\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Select thermal surfaces<a class=\"headerlink\" href=\"#select-thermal-surfaces\" title=\"Link to this heading\">\u00b6</a></h2><p>The four surface names are <code class=\"docutils literal notranslate\"><span class=\"pre\">floor</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">roof</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">side_left</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">side_right</span></code>.\nEach accepts a centred exposed fraction from 0 to 1:</p>", "a[href=\"#define-chamber-and-heat-exchanger-cross-sections\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Define chamber and heat-exchanger cross sections<a class=\"headerlink\" href=\"#define-chamber-and-heat-exchanger-cross-sections\" title=\"Link to this heading\">\u00b6</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">CrossSectionRounded</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">CrossSectionSquared</span></code> support both chamber sectors\nand independently dimensioned tubes. The geometry, hydraulic properties, and\nthermal surface selection use the same section objects.</p>", "a[href=\"../explanations/channel-construction.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Physical cooling-channel construction<a class=\"headerlink\" href=\"#physical-cooling-channel-construction\" title=\"Link to this heading\">\u00b6</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">build_channel_construction(circuit,</span> <span class=\"pre\">reference_path)</span></code> resolves a circuit\u2019s\nnominal winding into the section it physically occupies. The same resolved\ngeometry feeds the simulation, CAD, and the native 3D viewer, so a channel is\nsized once and drawn, meshed and solved from that one answer.</p>", "a[href=\"#occupied-sectors-and-existing-chamber-construction\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Occupied sectors and existing chamber construction<a class=\"headerlink\" href=\"#occupied-sectors-and-existing-chamber-construction\" title=\"Link to this heading\">\u00b6</a></h2><p>Alternatively, supply <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">angle</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">height</span></code>, without either width:</p>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/ChannelSection.html#pyskyfire.regen.cross_section.ChannelSection.Dh_coolant\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.ChannelSection.Dh_coolant\">\n<span class=\"sig-name descname\"><span class=\"pre\">Dh_coolant</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">prof</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/regen/index.html#module-pyskyfire.regen\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen<a class=\"headerlink\" href=\"#module-pyskyfire.regen\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/SectionProfiles.html#pyskyfire.regen.cross_section.SectionProfiles\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SectionProfiles</span></span></dt><dd><p>All geometry profiles along the cooling-channel centerline.</p><p>Each required array must have consistent length <code class=\"docutils literal notranslate\"><span class=\"pre\">N</span></code> (number of stations).</p></dd>", "a[href=\"#dimensions-and-wall-thickness\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Dimensions and wall thickness<a class=\"headerlink\" href=\"#dimensions-and-wall-thickness\" title=\"Link to this heading\">\u00b6</a></h2><p>All widths describe the <strong>internal fluid passage</strong>: the straight-line distance\nbetween the two sidewall endpoints at the floor or roof. A rounded width is a\nlobe chord, not its diameter or arc length. Every angle in these inputs uses\nradians.</p>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/ChannelSection.html#pyskyfire.regen.cross_section.ChannelSection.A_coolant\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.ChannelSection.A_coolant\">\n<span class=\"sig-name descname\"><span class=\"pre\">A_coolant</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">prof</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/ChannelSection.html#pyskyfire.regen.cross_section.ChannelSection.A_exterior\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.ChannelSection.A_exterior\">\n<span class=\"sig-name descname\"><span class=\"pre\">A_exterior</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">prof</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Area enclosed by the outside of the tube, including the passage [m\u00b2].</p></dd>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/CrossSectionRounded.html#pyskyfire.regen.cross_section.CrossSectionRounded\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.CrossSectionRounded\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CrossSectionRounded</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">16</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height_input</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'full'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure_angles</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">enable_fin</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ChannelSection</span></code></p><p>Two circular lobes connected by straight tangent sidewalls.</p><p>Both input routes build the same boundary: sector radius/angle/wall\nthickness, or internal floor and roof endpoint widths and height. Equal\nwidths give parallel sides; equal widths with full height equal to width\ngive a circle. A single wall thickness offsets all four surfaces.</p><p>height_input=\u201dfull\u201d measures bottom-to-top passage height; \u201cbase\u201d measures\nseparation of lobe centres. For unequal endpoint widths and full height,\nthe less steep of the two possible tangent constructions is selected.\nInvalid combinations raise rather than distorting the lobes. Angular\ninput retains its exact prescribed sidewall angle.</p></dd>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/ChannelSection.html#pyskyfire.regen.cross_section.ChannelSection.widths\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.ChannelSection.widths\">\n<span class=\"sig-name descname\"><span class=\"pre\">widths</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">prof</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Internal endpoint-to-endpoint floor and roof widths [m].</p></dd>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/ChannelSection.html#pyskyfire.regen.cross_section.ChannelSection.R_coolant_per_len\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.ChannelSection.R_coolant_per_len\">\n<span class=\"sig-name descname\"><span class=\"pre\">R_coolant_per_len</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">prof</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">k_wall</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">enable_fin</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Convection resistance per path length [K m/W], optionally with ribs.</p></dd>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/CrossSectionSquared.html#pyskyfire.regen.cross_section.CrossSectionSquared\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.CrossSectionSquared\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CrossSectionSquared</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">sidewall_half_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">8</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof_thickness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'arc'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'arc'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">enable_fin</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ChannelSection</span></code></p><p>Squared passages with independently straight or curved floor and roof.</p><p>sidewall_half_thickness [m] is ONE tube sidewall\u2019s normal thickness,\nequivalent to HALF the shared rib between adjacent chamber channels. A\nconstant or design-input callable is accepted. A former 1 mm full rib is\ntherefore specified as 0.5 mm here.</p><p>Floor thickness comes from SectionProfiles.t_wall. roof_thickness defaults\nto that thickness and may instead be a constant or callable. floor and roof\nindependently accept \u201carc\u201d or \u201cline\u201d. Direct width profiles use the\ndistance between internal sidewall endpoints. With sector profiles, the\nexisting constant-material-width rib construction determines those\nendpoints; choosing a line joins the same endpoints with a chord.</p></dd>", "a[href=\"#local-exchanger-profiles\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Local exchanger profiles<a class=\"headerlink\" href=\"#local-exchanger-profiles\" title=\"Link to this heading\">\u00b6</a></h2><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">SectionProfiles.from_dimensions</span></code> without a thrust chamber or placed\npath. Scalars and one-dimensional arrays broadcast over the supplied stations:</p>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/SectionProfiles.html#pyskyfire.regen.cross_section.SectionProfiles.from_dimensions\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles.from_dimensions\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_dimensions</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wall_thickness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor_width</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof_width</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">radius</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Build local section profiles without a chamber or placed path.</p><p>Supply both internal endpoint widths, or a finite radius and full\noccupied sector angle (radians). With widths, radius only controls\nsquared-arc curvature; omit it for straight ends. Dimensions broadcast\nover stations. <code class=\"docutils literal notranslate\"><span class=\"pre\">stations</span></code> is the local path coordinate in metres,\nexposed as <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> to design-input callables; it is not a placement.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
